<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Application\Usecase\Create;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Application\Service\Visibility\SmtpOutboundConfigVisibilityService;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\SmtpOutboundConfig;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\Gateway\SmtpOutboundConfigWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class SmtpOutboundConfigCreateUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly SmtpOutboundConfigVisibilityService $visibility,
        private readonly SmtpOutboundConfigWriteGateway $writer,
    ) {
    }

    public function allowCreate(): Allow
    {
        $this->logDebug("Check allow of create usecase for Smtp outbound config");
        $span = $this->startSpan("Check allow of create usecase for Smtp outbound config");
        try {
            $result = $this->dispatcher->dispatch(new SmtpOutboundConfigCreateAllowDecision(Allow::allowed('create', 'Allowed to create by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function create(SmtpOutboundConfigCreateParams $params): SmtpOutboundConfigCreateResult
    {
        $this->logDebug("Run create usecase for Smtp outbound config");
        $span = $this->startSpan("Run create usecase for Smtp outbound config");
        try {
            $allow = $this->allowCreate();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to create Smtp outbound config');
            }
            $this->dispatcher->dispatch(new SmtpOutboundConfigCreateCheck($params));
            $enriched = $this->dispatcher->dispatch(new SmtpOutboundConfigCreateEnrich($params, $params->toAttributes()));
            $attributes = $enriched->getResult();
            $input = $this->visibility->copyWithFixed($attributes);
            $entity = SmtpOutboundConfig::create($input);
            $result = $this->writer->create(
                $entity,
                fn (SmtpOutboundConfig $created) =>
                            $this->visibility->checkVisibility($created)
            );
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new SmtpOutboundConfigCreateResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
